#!/usr/bin/env python3
import sys, json

def main():
    try:
        text = sys.stdin.read()
        req = json.loads(text)
    except Exception:
        sys.stderr.write("invalid JSON\n")
        sys.exit(2)
    if not isinstance(req, dict):
        sys.stderr.write("input must be JSON object\n")
        sys.exit(2)
    if "subtotal_cents" not in req or "member" not in req:
        sys.stderr.write("missing required fields\n")
        sys.exit(2)
    subtotal = req["subtotal_cents"]
    member = req["member"]
    if not isinstance(subtotal, int) or isinstance(subtotal, bool):
        sys.stderr.write("subtotal_cents must be an integer\n")
        sys.exit(2)
    if subtotal < 0:
        sys.stderr.write("subtotal_cents must be non-negative\n")
        sys.exit(2)
    if not isinstance(member, bool):
        sys.stderr.write("member must be boolean\n")
        sys.exit(2)
    discount = subtotal // 10 if subtotal > 10000 else 0
    shipping = 0 if member else 750
    total = subtotal - discount + shipping
    out = {
        "subtotal_cents": subtotal,
        "discount_cents": discount,
        "shipping_cents": shipping,
        "total_cents": total,
    }
    sys.stdout.write(json.dumps(out))
    sys.stdout.flush()

if __name__ == "__main__":
    main()

